-- Reel Studio 0011: every account has its own profile (knowledge, voice, look, rules) and its own posting.
-- Nothing is shared: reels, ideas, learning, connections and posting are per account. Only We One Aviation has
-- connected platforms today, so reels of any other account are never posted anywhere (no cross-posting).

alter table public.brands add column if not exists profile jsonb not null default '{}'::jsonb;
update public.brands set profile = $weone${"version": 1, "name": "We One Aviation", "language": "hinglish", "voice": "female", "legacy_prompts": true, "instagram": "we_one_aviation", "note": "Uses the original Hinglish aviation prompts, lexicon, CTA and logo (unchanged)."}$weone$::jsonb where id = 'weone';
update public.brands set profile = $bmc${"version": 1, "updated": "2026-10-23", "name": "Book My Charter", "website": "https://bookmycharter.in", "instagram": null, "language": "english", "tts_lang": "en", "asr_lang": "en", "voice": "female", "tone": "Premium, calm and confident. Plain English, no hype words (no 'luxury lifestyle', 'elite', 'exclusive deal'). Explains how private flying really works, like a trusted insider. Short sentences. Every claim checkable.", "cta": {"say": "Follow Book My Charter.", "caption": "Follow *Book My Charter*"}, "end_title": "FOLLOW FOR MORE", "end_sub": "private flying, explained", "palette": {"accent": [212, 175, 92], "secondary": [233, 222, 196]}, "logo_file": "brands/bookmycharter/logo.png", "watermark": true, "niche": "private jet and helicopter charter in India", "business": "Book My Charter (bookmycharter.in) is a charter arranger based in Dwarka, Delhi. It plans and coordinates whole-aircraft charters across India: private jets, helicopters, turboprops and airliners for groups. It explains how a charter is priced and planned before anyone commits ('our job is planning, not selling'). It never publishes facts it cannot back with a dated source: no fleet counts, passenger totals or certification badges. Char Dham seat-based pilgrimage flights are handled by a sister site, Book My CharDham; Book My Charter covers chartering a whole aircraft.", "services": ["Private jet charter (light, midsize, super-midsize, large jets)", "Helicopter charter: helipads, venues, hills, sites with no runway", "Char Dham & Kedarnath private helicopter charter (whole aircraft)", "Empty leg flights (one-way repositioning flights, matched to a flexible window)", "Corporate charter (executive teams, multi-city days, recurring routes)", "Wedding helicopter: couple's arrival, flower shower, guest transfers", "Aerial flower dropping over weddings, temple events, ceremonies", "Air ambulance (stretcher, medical team, bed-to-bed planning)", "Cargo charter (urgent, oversized or sensitive freight)", "Group charter: whole airliner for 50 to 189 people (ATR 72, Q400, ERJ, Boeing 737)"], "fleet_facts": "Compares 52 aircraft types: 11 helicopters (4-12 seats), 9 light jets (5-9 seats), 12 midsize jets (7-9), 2 super-midsize (8-10), 5 large jets (8-16), 6 turboprops (5-11), 7 airliners (37-189). Flies from 154 Indian airports or an approved helipad; nearest-airport pages for 19,300 pincodes in 733 districts. Helicopters: range 540-1,020 km, 200-290 km/h, not practical beyond about 300 km. Example types: Agusta 109 Grand, Airbus H125 (hot-and-high, Char Dham), Airbus H145, Bell 407/429, Cessna Citation CJ2/XLS, Hawker 800XP, Learjet 45, Phenom 300, Falcon 2000, Legacy 650, Global 6000, Gulfstream G550, King Air B200/B300, Pilatus PC-12.", "pricing_logic": ["Hourly rate of the aircraft class is the biggest part of any quote; moving one cabin class changes price more than bargaining within one.", "Block time is billed from engine start to engine stop, not take-off to landing: a flight listed as 55 minutes is almost never billed as 55 minutes.", "Positioning: flying the aircraft to your departure city (and home again on one-way trips) is the usual reason two quotes for the same aircraft are far apart. Always ask where it is based.", "Landing, parking and ground handling at each stop; metro airports cost more than regional ones.", "Crew duty limits: a long day can need a second crew or an overnight stop.", "Waiting time: on weddings, events and site visits it is often the largest single line, more than the flying.", "Taxes and statutory charges on top; international flights need overflight and landing permits.", "A 'from' price that leaves out positioning and handling is not a real price."], "audience": ["Business owners and CXOs in Delhi NCR, Mumbai, Ahmedabad, Bengaluru, Hyderabad, Jaipur", "Wedding families and wedding planners (helicopter entry, flower shower, destination weddings in Udaipur, Jaipur, Goa)", "HNI families and NRIs visiting home towns with no direct flights", "Pilgrims who want a private helicopter for Kedarnath / Char Dham", "Event and film production teams; companies moving groups", "Hospitals and families needing an air ambulance", "Aviation fans curious how private flying works"], "usp": ["Transparent: shows how the price is built, line by line, instead of a headline figure", "Planning-first: checks runway, range, crew duty, weight and permissions before quoting", "One point of contact from booking to arrival, including helipad and ground coordination", "Honest about limits (empty legs are flexible, not guaranteed; helicopters suit short hops)"], "competitors": [{"name": "JetSetGo", "note": "Delhi-based marketplace; offices in Mumbai, Bengaluru, Dubai, New York; empty-leg programme 'JetSteals'; helicopter services."}, {"name": "Club One Air", "note": "New Delhi; says it is India's oldest luxury charter operator; air ambulance."}, {"name": "Taj Air", "note": "Tata Sons-owned NSOP, Mumbai GA terminal lounge, Falcon 2000 fleet; Taj hospitality standards."}, {"name": "Airborne Private Jet", "note": "Mumbai; publishes a per-minute price list; medical evacuation, cargo, organ transfer."}, {"name": "Paramount Business Jets", "note": "US-based broker, claims 4,000+ aircraft worldwide."}, {"name": "Blueheights Aviation", "note": "Helicopter-focused charter."}], "competitor_gap": "Competitors sell glamour and 'from' prices. Book My Charter's edge on Instagram is the insider explainer: how the money really works, which aircraft fits, what can go wrong and how planning avoids it. Premium visuals, zero hype, every number sourced.", "market_facts": [{"fact": "Business aviation movements at major Indian airports rose about 17% year-on-year in Q1 2026; Ahmedabad +26.1% (938 to 1,183), Mumbai +12.3% (2,251 to 2,527), Delhi +1.4%.", "source": "https://ai.avi-go.com/news/ai-news-center/insights/india-business-aviation-surges-17-in-q1-2026-daily-20260501-4", "date": "2026-05-01"}, {"fact": "India has 229 billionaires (Forbes) but fewer than 200 registered business jets; private-use aircraft attract 28% IGST plus 3% compensation cess, versus 5% IGST for NSOP charter aircraft.", "source": "https://www.globalair.com/articles/indias-private-jet-market-is-stuck-at-200-planes-its-tax-policy-is-why/12653", "date": "2026-09-10"}, {"fact": "India's business jet market was valued at $692.3 million in 2025 (IMARC); over 80% of fixed-wing imports are pre-owned.", "source": "https://www.globalair.com/articles/indias-private-jet-market-is-stuck-at-200-planes-its-tax-policy-is-why/12653", "date": "2026-09-10"}, {"fact": "Helicopter baraats (groom arriving by helicopter) are a rising wedding trend across Haryana districts (Karnal, Nuh, Sirsa, Faridabad).", "source": "https://www.etvbharat.com/en/!state/helicopter-baraat-the-rising-trend-of-using-helicopters-at-weddings-in-haryana-enn25030901832", "date": "2025-03-09"}], "pillars": [{"id": "price_decoded", "name": "Price, decoded", "why": "Money curiosity + insider secret = saves and sends. Unique to this brand."}, {"id": "which_aircraft", "name": "Which aircraft?", "why": "Practical, savable comparisons (jet vs helicopter vs turboprop, light vs midsize)."}, {"id": "big_moments", "name": "Big moments", "why": "Weddings, flower showers, family trips: emotional, highly shareable in India."}, {"id": "time_math", "name": "Door-to-door time math", "why": "Contrarian truth: a private jet is not faster in the air; it saves the day on the ground."}, {"id": "routes", "name": "Routes & places", "why": "Delhi-Udaipur, Delhi-Leh, Mumbai-Goa: aspirational, location-tagged, searchable."}, {"id": "industry", "name": "Inside Indian private aviation", "why": "Timely numbers and news; authority for business audiences."}, {"id": "myths", "name": "Myth vs fact", "why": "Contradiction hooks stop the scroll; corrects common misconceptions."}, {"id": "missions", "name": "Missions", "why": "Air ambulance, cargo, group charter, aerial work: surprising uses people never considered."}], "hook_patterns": ["Your quote is missing a line. (hidden-cost curiosity)", "Nobody tells you this before you book a private jet.", "A private jet is not faster. Here is what it actually saves.", "The cheapest private jet seat is the one flying empty.", "Two quotes. Same jet. Same route. Lakhs apart. Why?", "Before you book a helicopter for your wedding, know this.", "This is what 'thin air' does to a helicopter at Kedarnath.", "Three questions decide your aircraft. Price is not one of them."], "topic_bank": [{"title": "The line missing from your private jet quote", "hook": "Your private jet quote is missing one line. It is usually the biggest one.", "pillar": "price_decoded", "facts": ["Positioning = flying the aircraft to your departure city and back to base on one-way trips", "It is the usual reason two quotes for the same aircraft on the same route are far apart"], "source": "https://bookmycharter.in/pricing"}, {"title": "A 55-minute flight is never billed as 55 minutes", "hook": "Your flight is 55 minutes. Your bill isn't.", "pillar": "price_decoded", "facts": ["Block time runs from engine start to engine stop", "Taxi, routing, holding and winds add billed time"], "source": "https://bookmycharter.in/pricing"}, {"title": "The cheapest private jet seat is flying empty", "hook": "Right now, a private jet is flying somewhere with zero passengers.", "pillar": "price_decoded", "facts": ["Every charter can create empty repositioning legs", "Same aircraft and crew; route and date fixed by someone else's booking", "Can change or disappear if the original trip changes"], "source": "https://bookmycharter.in/insights/what-is-an-empty-leg-flight"}, {"title": "Why the waiting costs more than the flight", "hook": "At most helicopter weddings, the flying is not the expensive part.", "pillar": "price_decoded", "facts": ["Waiting time is charged while the aircraft stays on the ground for you", "On event and site-visit trips it is often the largest single line"], "source": "https://bookmycharter.in/pricing"}, {"title": "A 'from' price is not a price", "hook": "If a charter price says 'from', read this first.", "pillar": "myths", "facts": ["A 'from' price that leaves out positioning and handling is not a real price", "A full quote shows what is included and what is not"], "source": "https://bookmycharter.in/"}, {"title": "A private jet is not faster in the air", "hook": "A private jet is not faster than your airline. So why do CEOs fly it?", "pillar": "time_math", "facts": ["Cruise speed of a business jet and an airliner is similar", "Time is saved on the ground: no connections, early check-in or distant hubs", "On busy routes like Delhi-Mumbai a commercial ticket for one person is much cheaper"], "source": "https://bookmycharter.in/insights/private-jet-vs-commercial-flight"}, {"title": "Helicopter or jet? Your destination decides", "hook": "Helicopter or private jet? You don't get to choose. Your destination does.", "pillar": "which_aircraft", "facts": ["Helicopters land at sites, not airports; not practical beyond about 300 km", "Jets need a runway at both ends; on flights under about an hour most speed advantage is lost in climb and descent", "Often used together: jet for the long leg, helicopter for the last mile"], "source": "https://bookmycharter.in/insights/helicopter-vs-private-jet"}, {"title": "The 3 questions that pick your aircraft", "hook": "Three questions decide your aircraft. Price is not one of them.", "pillar": "which_aircraft", "facts": ["Where you land, how far you fly, how many people travel, in that order"], "source": "https://bookmycharter.in/"}, {"title": "Light jet vs midsize jet", "hook": "In a light jet, you can't stand up. Here's when that doesn't matter.", "pillar": "which_aircraft", "facts": ["Light jets: 5-9 seats, short city pairs of about 1-3 hours, most efficient way to fly a jet", "Moving up one cabin class changes price more than almost anything else"], "source": "https://bookmycharter.in/aircraft/private-jets"}, {"title": "189 people, one flight: group charter", "hook": "Your whole wedding party can fly together. All 189 of them.", "pillar": "missions", "facts": ["Group charter = whole airliner for about 50 to 189 people", "Boeing 737-800 seats 160-189; ATR 72 seats 68-78"], "source": "https://bookmycharter.in/services/group-charter"}, {"title": "The flower shower everyone films", "hook": "Everyone films the helicopter flower shower. Nobody sees what it takes.", "pillar": "big_moments", "facts": ["A short flight that releases petals over a wedding, temple event or ceremony", "The site and the crowd below matter more than the flying"], "source": "https://bookmycharter.in/services/aerial-flower-dropping"}, {"title": "Before you book a wedding helicopter", "hook": "Before you book a helicopter for your wedding, know this.", "pillar": "big_moments", "facts": ["Flown to a venue site approved for landing", "Book as soon as the date is fixed: the landing site and permissions take time", "Events with a fixed moment need a backup plan"], "source": "https://bookmycharter.in/helicopter-charter/wedding-helicopter"}, {"title": "What thin air does to a Kedarnath helicopter", "hook": "At Kedarnath, a helicopter can carry less than its seats. Here's why.", "pillar": "which_aircraft", "facts": ["Payload is limited by density altitude (thin air) and checked against actual passenger weights", "Small high-altitude helipad; weather can close it at short notice", "Waiting at the shrine is part of the chartered day"], "source": "https://bookmycharter.in/chardham/kedarnath-helicopter"}, {"title": "An air ambulance is not a flying ambulance", "hook": "An air ambulance is not just a faster ambulance.", "pillar": "missions", "facts": ["Aircraft fitted with stretcher and medical equipment, medical team on board", "Treating doctor and air ambulance team confirm the patient is fit to fly", "Bed-to-bed planning between hospitals"], "source": "https://bookmycharter.in/services/air-ambulance"}, {"title": "Delhi to Udaipur in about an hour", "hook": "Delhi to Udaipur. About an hour. No connections.", "pillar": "routes", "facts": ["541 km straight line", "About 1 h 5 min to 1 h 10 min by business jet", "Helicopter not practical beyond about 300 km"], "source": "https://bookmycharter.in/routes/delhi-to-udaipur"}, {"title": "Delhi to Leh by private jet", "hook": "Delhi to Leh in about 75 minutes. The aircraft choice is the hard part.", "pillar": "routes", "facts": ["622 km straight line", "About 1 h 15 min to 1 h 20 min by business jet", "Turboprop about 1 h 35 min to 2 h 5 min"], "source": "https://bookmycharter.in/routes/delhi-to-leh"}, {"title": "India's billionaires vs India's jets", "hook": "India has 229 billionaires. And fewer than 200 business jets.", "pillar": "industry", "facts": ["229 billionaires (Forbes); fewer than 200 registered business jets", "Private-use aircraft: 28% IGST + 3% cess; NSOP charter aircraft: 5% IGST"], "source": "https://www.globalair.com/articles/indias-private-jet-market-is-stuck-at-200-planes-its-tax-policy-is-why/12653"}, {"title": "Private flying in India grew 17% in one quarter", "hook": "Private jet traffic in India jumped 17% in three months. One city led it.", "pillar": "industry", "facts": ["Q1 2026: business aviation movements up about 17% year-on-year at major airports", "Ahmedabad +26.1%, Mumbai +12.3%, Delhi +1.4%"], "source": "https://ai.avi-go.com/news/ai-news-center/insights/india-business-aviation-surges-17-in-q1-2026-daily-20260501-4"}, {"title": "Why your crew might need to sleep over", "hook": "Your day trip looks easy. The crew's legal clock says otherwise.", "pillar": "price_decoded", "facts": ["Crew duty limits are legal limits on a crew's working day", "Ground time counts; a long day can need a second crew or an overnight stop"], "source": "https://bookmycharter.in/pricing"}, {"title": "Can a helicopter land at your venue?", "hook": "Can a helicopter land at your farmhouse? Sometimes. Here's what decides it.", "pillar": "which_aircraft", "facts": ["A helicopter can land at a helipad or suitable open ground once the site and permission are checked", "Height, temperature, obstacles and site size matter more than the cabin"], "source": "https://bookmycharter.in/aircraft/helicopters"}, {"title": "Empty legs: who they suit and who they don't", "hook": "Empty legs are perfect for some travellers. A disaster for others.", "pillar": "myths", "facts": ["Suit: a destination but no fixed date, can leave at a day or two's notice", "Do not suit: fixed meetings, ceremonies, connecting flights"], "source": "https://bookmycharter.in/empty-leg-charter"}, {"title": "The jet that lands closer to home", "hook": "The nearest airport isn't always the one your jet can use.", "pillar": "which_aircraft", "facts": ["Runway length, range, altitude, passengers and baggage narrow the choice before price", "Some smaller airfields have little or no ground handling"], "source": "https://bookmycharter.in/how-it-works"}, {"title": "How a charter is booked in 5 steps", "hook": "Booking a private jet takes 5 steps. Most people think it's 50.", "pillar": "myths", "facts": ["Share route, date and group size; aircraft that fit are found; itemised quote; you choose; journey coordinated", "Route, date and passenger count are enough to start"], "source": "https://bookmycharter.in/how-it-works"}, {"title": "Six seats, one invoice", "hook": "A private jet is priced per aircraft, not per seat. That changes the maths.", "pillar": "time_math", "facts": ["Charter is priced per aircraft, not per seat", "Compare with the full cost of the airline journey: several premium tickets, transfers and a hotel night caused by a bad connection"], "source": "https://bookmycharter.in/insights/private-jet-vs-commercial-flight"}], "visual_style": {"look": "Premium and cinematic: golden hour, night tarmac lights, polished cabins, wide aerials. Calm motion, no shaky or cheap-looking clips. Gold accents on deep navy glass cards.", "footage_keywords": ["private jet takeoff sunset", "business jet interior leather seats", "private jet tarmac night", "helicopter landing helipad", "helicopter aerial mountains", "luxury wedding venue aerial", "palace hotel udaipur aerial", "airport runway lights night", "cockpit sunset clouds", "champagne glass airplane window", "businessman airport private terminal", "city skyline aerial dusk"], "avoid": ["crash or emergency footage", "cramped economy cabins", "cartoonish graphics", "money-throwing or flashy lifestyle clichés"], "mood": "calm", "graphics": "Use counters for numbers, compare cards for A vs B, list_card for checklists, chips for labels. No lightning bolts or shake effects."}, "rules": ["Never quote a rupee price for a specific trip; prices depend on aircraft, positioning, waiting and taxes. Explain the structure instead.", "Never claim fleet ownership, safety records, certifications, passenger counts or 'best/cheapest'.", "Never imply guaranteed empty-leg availability.", "No crash, accident or live-investigation topics.", "Do not name competitors in reels.", "Char Dham seat/package pilgrimage flights belong to Book My CharDham; only whole-aircraft charter here.", "No phone numbers, links or WhatsApp in the reel itself."], "hashtags": ["privatejet", "helicoptercharter", "privatejetcharter", "bookmycharter", "privateaviation"]}$bmc$::jsonb where id = 'bookmycharter';

-- posting targets belong to one account: an account without its own connections posts nowhere
create or replace function public.post_targets(p_auto boolean, p_brand text) returns jsonb language sql stable security definer set search_path = '' as $$
  select case when coalesce(p_brand, 'weone') = 'weone' then public.post_targets(p_auto) else '{}'::jsonb end;
$$;
revoke all on function public.post_targets(boolean, text) from public, anon, authenticated;

create or replace function public.set_review_decision(p_job uuid, p_decision text, p_notes text default null)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs;
begin
  if not public.is_member() then raise exception 'Your account is not on the members list.'; end if;
  if p_decision not in ('approve', 'reject') then raise exception 'bad decision'; end if;
  select * into j from public.jobs where id = p_job and kind = 'reel' for update;
  if not found then raise exception 'This reel no longer exists.'; end if;
  if j.status = 'done' and p_decision = 'approve' then return j; end if;
  if j.status <> 'review' then raise exception 'This reel is no longer waiting for review.'; end if;
  update public.jobs
     set status = case when p_decision = 'approve' then 'done' else 'cancelled' end,
         output = output || jsonb_build_object('decision', p_decision, 'notes', p_notes, 'decided_at', now())
                         || case when p_decision = 'approve' and public.autopost_on() then public.post_targets(false, j.brand) else '{}'::jsonb end
   where id = p_job returning * into j;
  return j;
end $$;

-- the 5-minute auto-post timer only runs for accounts that have their own connected platforms
create or replace function public.auto_approve_due() returns int language plpgsql security definer set search_path = '' as $$
declare n int; night boolean;
begin
  if not public.autopost_on() then return 0; end if;
  night := (now() at time zone 'Asia/Kolkata')::time not between time '07:30' and time '23:00';
  update public.jobs
     set status = 'done',
         output = output || jsonb_build_object('decision', 'auto', 'decided_at', now()) || public.post_targets(true, brand)
   where kind = 'reel' and status = 'review' and brand = 'weone'
     and coalesce((output ->> 'hold')::boolean, false) = false
     and coalesce((output ->> 'autopilot_hold')::boolean, false) = false
     and not (night and input ? 'autopilot')
     and (output ->> 'review_deadline')::timestamptz <= now();
  get diagnostics n = row_count;
  return n;
end $$;

create or replace function public.set_post(p_job uuid, p_platform text, p_action text)
returns public.jobs language plpgsql security definer set search_path = '' as $$
declare j public.jobs; st text; label text;
begin
  if not public.is_member() then raise exception 'Your account is not on the members list.'; end if;
  if p_platform not in ('ig', 'li', 'fb') or p_action not in ('now', 'off') then raise exception 'bad request'; end if;
  label := case p_platform when 'ig' then 'Instagram' when 'li' then 'LinkedIn' else 'Facebook' end;
  select * into j from public.jobs where id = p_job and kind = 'reel' for update;
  if not found then raise exception 'This reel no longer exists.'; end if;
  if j.brand <> 'weone' and p_action = 'now' then raise exception 'Connect this account''s own % first. Reels never post to another account.', label; end if;
  if j.status <> 'done' then raise exception 'Approve the reel first.'; end if;
  st := j.output -> p_platform ->> 'state';
  if st = 'posted' then raise exception 'It is already on %.', label; end if;
  if st in ('posting', 'uploading', 'processing') then raise exception 'It is being posted to % right now.', label; end if;
  update public.jobs set output = output || jsonb_build_object(p_platform,
      coalesce(output -> p_platform, '{}'::jsonb) - 'error' - 'at' ||
      case when p_action = 'off' then jsonb_build_object('state', 'off')
           else jsonb_build_object('state', 'scheduled', 'at', now(), 'attempts', 0, 'manual', true) end)
   where id = p_job returning * into j;
  return j;
end $$;
